export declare const styles = "\n  :host {\n    \n  --_color: var(--ring-color, #1d8049);\n  --_track: var(--ring-track, #dbe2dd);\n  --_bg: var(--ring-bg, #ffffff);\n  --_fg: var(--ring-fg, #0d1310);\n\n    position: fixed;\n    right: calc(var(--ring-inset, 20px) + env(safe-area-inset-right, 0px));\n    bottom: calc(var(--ring-inset, 20px) + env(safe-area-inset-bottom, 0px));\n    z-index: var(--ring-z, 40);\n    display: block;\n    width: 48px;\n    height: 48px;\n    pointer-events: none;\n  }\n\n  :host([theme='dark']) {\n    \n  --_color: var(--ring-color, #43c97e);\n  --_track: var(--ring-track, #1f2622);\n  --_bg: var(--ring-bg, #101411);\n  --_fg: var(--ring-fg, #e9eeea);\n\n  }\n\n  @media (prefers-color-scheme: dark) {\n    :host(:not([theme='light'])) {\n      \n  --_color: var(--ring-color, #43c97e);\n  --_track: var(--ring-track, #1f2622);\n  --_bg: var(--ring-bg, #101411);\n  --_fg: var(--ring-fg, #e9eeea);\n\n    }\n  }\n\n  :host([hidden]) {\n    display: none;\n  }\n\n  .button {\n    position: relative;\n    display: grid;\n    place-items: center;\n    width: 48px;\n    height: 48px;\n    padding: 0;\n    border: 0;\n    border-radius: 50%;\n    background: var(--_bg);\n    box-shadow: 0 6px 18px -6px rgba(0, 0, 0, 0.3);\n    color: var(--_fg);\n    font: inherit;\n    cursor: pointer;\n    opacity: 0;\n    visibility: hidden;\n    transform: translateY(12px);\n    transition:\n      opacity 0.25s ease,\n      transform 0.25s ease,\n      visibility 0s linear 0.25s;\n    -webkit-tap-highlight-color: transparent;\n  }\n\n  :host([visible]) .button {\n    opacity: 1;\n    visibility: visible;\n    transform: none;\n    pointer-events: auto;\n    transition:\n      opacity 0.25s ease,\n      transform 0.25s ease,\n      visibility 0s;\n  }\n\n  .button:focus-visible {\n    outline: 2px solid var(--_color);\n    outline-offset: 3px;\n  }\n\n  .ring {\n    position: absolute;\n    inset: 0;\n    width: 100%;\n    height: 100%;\n    transform: rotate(-90deg);\n    fill: none;\n    stroke-width: 2;\n  }\n\n  .track {\n    stroke: var(--_track);\n  }\n\n  .bar {\n    stroke: var(--_color);\n    stroke-linecap: round;\n    stroke-dasharray: 100;\n  }\n\n  .arrow {\n    position: relative;\n    width: 18px;\n    height: 18px;\n    fill: none;\n    stroke: currentColor;\n    stroke-width: 2;\n    stroke-linecap: round;\n    stroke-linejoin: round;\n    transition: transform 0.2s ease;\n  }\n\n  .button:hover .arrow {\n    transform: translateY(-2px);\n  }\n\n  @media (prefers-reduced-motion: reduce) {\n    .button,\n    :host([visible]) .button {\n      transform: none;\n    }\n\n    .arrow,\n    .button:hover .arrow {\n      transform: none;\n      transition: none;\n    }\n  }\n";
